/**
 * Applying the committed migrations.
 *
 * The SQL in `drizzle/` is generated by `pnpm db:generate` and committed; nothing generates SQL at
 * run time. `runMigrations` only has to find that folder and hand it to the migrator that matches the
 * driver behind the `AppDb`.
 */
import { existsSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { migrate as migrateNodePg } from 'drizzle-orm/node-postgres/migrator'
import type { NodePgDatabase } from 'drizzle-orm/node-postgres'
import { migrate as migratePglite } from 'drizzle-orm/pglite/migrator'
import type { PgliteDatabase } from 'drizzle-orm/pglite'
import type { AppDb } from './client.js'
import type * as schema from './schema.js'

/**
 * Walks up from this module to the first directory holding a migrations journal. That is
 * `<package>/drizzle` whether this file is running from `src/db/` under vitest or from `dist/db/`
 * in the container, because the build copies `drizzle/` next to `dist/`.
 */
export function migrationsFolder(): string {
  let dir = dirname(fileURLToPath(import.meta.url))
  for (;;) {
    const candidate = join(dir, 'drizzle')
    if (existsSync(join(candidate, 'meta', '_journal.json'))) return candidate
    const parent = dirname(dir)
    if (parent === dir) throw new Error('no drizzle migrations folder found above ' + fileURLToPath(import.meta.url))
    dir = parent
  }
}

export async function runMigrations(db: AppDb, kind: 'pg' | 'pglite'): Promise<void> {
  const config = { migrationsFolder: migrationsFolder() }
  // `AppDb` is the supertype both driver databases satisfy; `kind` is the caller telling us which
  // one this actually is, which is the one thing the type cannot say.
  if (kind === 'pg') await migrateNodePg(db as NodePgDatabase<typeof schema>, config)
  else await migratePglite(db as PgliteDatabase<typeof schema>, config)
}
